class Solution:
    def maximumRobots(self, chargeTimes, runningCosts, budget):
        from collections import deque
        pre=[0]
        for x in runningCosts: pre.append(pre[-1]+x)
        dq=deque(); l=0; ans=0
        for r,c in enumerate(chargeTimes):
            while dq and chargeTimes[dq[-1]]<=c: dq.pop()
            dq.append(r)
            while dq and chargeTimes[dq[0]]+(r-l+1)*(pre[r+1]-pre[l])>budget:
                if dq[0]==l: dq.popleft()
                l+=1
            ans=max(ans,r-l+1)
        return ans

