class Solution {
public:
    int maximumRobots(vector<int>& ct, vector<int>& rc, long long budget){
        int n=ct.size(), l=0, ans=0;
        vector<long long> pre(n+1,0);
        for(int i=0;i<n;i++) pre[i+1]=pre[i]+rc[i];
        deque<int> dq;
        for(int r=0;r<n;r++){
            while(!dq.empty()&&ct[dq.back()]<=ct[r]) dq.pop_back();
            dq.push_back(r);
            while(!dq.empty()&&(long long)ct[dq.front()]+(r-l+1)*(pre[r+1]-pre[l])>budget){
                if(dq.front()==l) dq.pop_front();
                l++;
            }
            ans=max(ans,r-l+1);
        }
        return ans;
    }
};

