class Solution {
    public int maximumRobots(int[] ct, int[] rc, long budget){
        int n=ct.length,l=0,ans=0;
        long[] pre=new long[n+1];
        for(int i=0;i<n;i++) pre[i+1]=pre[i]+rc[i];
        ArrayDeque<Integer> dq=new ArrayDeque<>();
        for(int r=0;r<n;r++){
            while(!dq.isEmpty()&&ct[dq.peekLast()]<=ct[r]) dq.pollLast();
            dq.addLast(r);
            while(!dq.isEmpty()&&(long)ct[dq.peekFirst()]+(r-l+1)*(pre[r+1]-pre[l])>budget){
                if(dq.peekFirst()==l) dq.pollFirst();
                l++;
            }
            ans=Math.max(ans,r-l+1);
        }
        return ans;
    }
}

