var maximumRobots = function(ct, rc, budget) {
    const n=ct.length; let l=0,ans=0;
    const pre=[0]; for(const x of rc) pre.push(pre[pre.length-1]+x);
    const dq=[];
    for(let r=0;r<n;r++){
        while(dq.length && ct[dq[dq.length-1]]<=ct[r]) dq.pop();
        dq.push(r);
        while(dq.length && ct[dq[0]]+(r-l+1)*(pre[r+1]-pre[l])>budget){
            if(dq[0]===l) dq.shift();
            l++;
        }
        ans=Math.max(ans,r-l+1);
    }
    return ans;
};
